python3 -c "
import openpyxl, json
wb = openpyxl.load_workbook('/workspace/maternal_health.xlsx', data_only=False)
data = {}
for name in wb.sheetnames:
    sheet = wb[name]
    rows = []
    for r in sheet.iter_rows(values_only=True):
        if any(r):
            rows.append(list(r))
    data[name] = rows
print(json.dumps(data, indent=2))
"

